# SVGをPNGに変換し、バイトデータを取得
png_data = cairosvg.svg2png(bytestring=SVG_CODE.encode('utf-8'))

# BytesIOオブジェクトに変換
png_buffer = io.BytesIO(png_data)

# matplotlibで画像を読み込み
img = mpimg.imread(png_buffer, format='png')

# 画像を表示
plt.imshow(img)
plt.axis('off')  # 軸を非表示に
plt.show()





